class Solution { int maximumRow(vector<vector<int>>& mat,int col){int row=0;for(int i=1;i<(int)mat.size();++i)if(mat[i][col]>mat[row][col])row=i;return row;}public: vector<int> findPeakGrid(vector<vector<int>>& mat){int left=0,right=mat[0].size()-1;while(left<right){int middle=(left+right)/2,row=maximumRow(mat,middle);if(mat[row][middle]<mat[row][middle+1])left=middle+1;else right=middle;}return {maximumRow(mat,left),left};} };
